*******************************************************************			 ******	       Setup		 ******			 ******			 ******  This is the master file for loading ROM patches.	 ******  This small file looks at the ROM version and	 ******  decides which patch file to load and execute.	 ******			 ***			 **************************************************************************************************************************************			 ******	      Version 3.0		 ******			 ******	    March 12, 1989		 ******			 ******			 ****** For version 2.0	or greater of the ROM.  This is	 ****** different from earlier versions in that the patches	 ****** are in different files and this file only loads them.	 ******			 ****** 29 Feb 88	Steven Glass		 ******			 ****** Added code to get and dispose of handles so that enough	 ****** master handles are made early.		 ******			 ******			 ****** 02 Dec 88	Steven Glass		 ******			 ****** Zeroed DefaultTPT before calling SetDefaultTPT.	 ******			 ******			 ******			 ****** 06 Feb 89	Mensch		 ******			 ****** Added test for system memory size. If the memorysize	 ****** of the system if <512K then we use patch file A	 ****** else we use patch file B		 ******			 ****** 24 Feb 89	Steven Glass		 ******			 ****** The SmallMemThreshold value was 8 but the compare was	 ****** for strictly less than.  I changed it to 9.	 ******			 ******			 ****** 12 Mar 89	Steven Glass		 ******			 ****** Asked GQuit to remove from memory.  Got different ID	 ****** for files that I load.  Removed code that looks for	 ****** TS2A and TS2B.  Only TS2 is used again.  Small mem	 ****** smarts are in TS2.		 ******			 ****** 30 Nov 89	Harry Yee		 ****** 			 ****** Put in fix for call GetNewID. It needs to be done here	 ****** because the patch file is not loaded soon enough. 	 ****** BRC #53470. The first ID reserved is always lost (this   ****** only happens on Tenspeed ROMs). So what we do is just    ****** call GetNewID with any main ID.		 ******			 ********************************************************************* BEGIN 6.0** 24-Sep-90	Dave Lyons** Added a PurgeAll($A000) and CompactMem after calling the* TSx patch.** 27-Mar-91	Dave Lyons** Added a real error message for failure to load the TSx* file (it was just a BRK $FF before).** 17-Sep-91	Dave Lyons** Rolling patches common to both TS2 and TS3 into Tool.Setup.* Strategy:  We call SetTSPtr on commonly-patched tool sets,* and then we call TSx, which is guaranteed to call SetTSPtr* again on all the tool sets we patched.  The FPTs contained* in Tool.Setup are only needed temporarily.  When we're done,* our main segment goes away (it loads in high memory).** 27-Jan-92	Dave Lyons** Added patch to $E10094 vector for both ROM 1 and ROM 3.* The patch sets the bank register to $00 around the call,* because we never documented that you had to do that, and* 3rd-party software is trashing memory when the firmware* winds up storing to RAM instead of softswitches. -- The* patch code is in Patch3:Misc.tools.pch.******************************************************************* BEGIN 6.0.1** 20-Aug-92	Dave Lyons** Added entries for AlertMessage and DoSysPrefs.************************************************************************************************************************************			 ******			 ******            Copyright (C) Apple Computer, Inc.	 ******            1985-1991		 ******            All Rights Reserved		 ******			 ******			 *******************************************************************	eject; This ROM patch file is an INIT file.	An init file is a file; that GS/OS loads and runs before it runs any applications.; This particular file is called Tool.Setup.  GS/OS loads and; runs this file before any other init files.  If GS/OS cannot; find this init file on the disk, it will not complete the; boot process.	include 'all.macros'	include ':::sys.equs.asm'	include ':::desk:Desk.Equates.asm'PendingSysBeep2	equ $E1167ESetup	PROC EXPORT	import AddTBNotifyProc	import AddTBRequestHandler	import DoCommonPatches;----------------------------------------------------;; Before anything else call this routine of Fern's; to try and reinitialize certain Apple	Desk Top Bus; devices since they don't seem to power up correctly.;;----------------------------------------------------*** 27-Jan-92 DAL -- force Bank to 0	phb	pea 0	plb	plb*** end 27-Jan-92	sep #$30	longa off	longi off;;;	lda >StateReg	lda StateReg	;abs addr, 27-Jan-92 DAL	pha	lda #$0C;;;	sta >StateReg	sta StateReg	;abs addr, 27-Jan-92 DAL	sec	jsl $E10094	; Fern's vector	pla;;;	sta >StateReg	sta StateReg	;abs addr, 27-Jan-92 DAL	rep #$30	longa on	longi on;;;	plb	;27-Jan-92 DAL -- restore bank, but optimize out;;;;;;	phb	; save data bank register	phk	plb;-----------------------------------------------------;; Look at the version number of QuickDraw to decide; what ROM this is.	 Based on this value load and; execute the appropriate file.;;----------------------------------------------------	pha	_QDVersion	pla	and #$7F00	cmp #$0100	; is this rom1?	beq ItsOne;; Fix for GetNewID which always loses the first ID reserved, thus making it ; possible for two programs to get the same ID. BRC #53470.;	pha	; space for result	pea $5000	; any type is fine	_GetNewID	pla		pha	_TLVersion	pla	and #$7F00	cmp #$0400	; if >= ROM 4 then don't patch.	bcc ItsOne	brl SkipPatchItsOne	xba	; take this value and make	clc	; it into an ascci char	adc #'0'	sep #$30	; only put one byte	into patch	sta LastDigit	; put char at end of path name	sta ErrorMsgDigit	rep #$30	; back to 16 bit mode;-----------------------------------------------------------;; Get 200 handles now so that the launcher and most other; apps will not run out.  ;; This code was added on 29 Feb 88 to solve problem of ; the launcher getting out of memory error when there was; still memory available.  The memory was all special and; no new handles could be made.;;;----------------------------------------------------SpecialIDForHandles	equ $4F01	ldy #200@1	phy	pha	; space for handle	pha	PushLong #0	; size 0	PushWord #SpecialIDForHandles	PushWord #0	pha	pha	_NewHandle	plx	plx	bcc @dontDie	brl Die@dontDie	ply	dey	bpl @1	PushWord #SpecialIDForHandles	_DisposeAll	jsr DoCommonPatches	;17-Sep-91 DAL	pha	; get My userID	PushWord #$A000	_GetNewID	pla	sta patchID	phx	; space for zp segment size	phx	; space for zp segment starting address	phx	; space for starting address	phx	phx	; space for userid	pha	; Push the Tools userID	PushLong #PatchName	PushWord #$ffff	; Not in special memory	_InitialLoad	bcs Die	ply	; don't need user id	plx	; need starting addr in x,a	pla	; (x has low, a has	high)	ply	; don't need zp adr	ply	; don't need zp seg size.	stx SelfModCall+1	sep #$20	sta SelfModCall+3	rep #$20SelfModCall	jsl $777777	pea $A000	_PurgeAll	_CompactMem;-------------------------------------------------;; Call SetDefaultTPT to make the current TPT; the default one.;; Note:  This may return an error but that's okay; since stack is not hurt.;; Zero the DefaultTPT since this is the first time ; it is referenced.;;----------------------------------------------------	lda #0	sta >DefaultTPTPtr	sta >DefaultTPTPtr+2	_SetDefaultTPTSkipPatch	jsl AddTBNotifyProc	jsl AddTBRequestHandler	plb	; restore dbr;; Now unload this segment of code be sure to do a jump instead; of a jsl this way we don't have to worry about whether this code; disappears...;	pha	; DAL 18-Sep-90	_MMStartUp	; DAL 18-Sep-90	plx	; DAL 18-Sep-90	longa off	sep #$20	pla	ply	; get the return address from the stack	phx	pea $0001	; and our file num...	pea $0001	; even our segment number...	phy	pha	; put the return address back...	longa On	rep #$20	ldx #$0C11	; and make the UnloadsegNumCall	jml >$E10000	; and call the tool locator...Die	pha	pushlong #FailureMessage	_SysFailMgr	brk $FFFailureMessage	dc.b FailMsgEnd-FailureMessage	dc.b 'Could not load setup file: TS*',13	dc.b 'Please use the Installer to set up your',13	dc.b 'boot disk correctly for this GS',13,13	dc.b 'Error='FailMsgEndErrorMsgDigit	equ FailureMessage+30PatchID	ds.W 1PatchName	str '*/System/System.Setup/TS*'LastDigit	equ *-1MemLevel	equ LastDigit+1	ENDP****************************************************************** DoCommonPatches -- install patches common to ROM 1 and ROM 3*****************************************************************DoCommonPatches	proc	import LocatorCallTable,MTCallTable,DeskCallTable	import ToBramSetupPatch,oldToBramSetupCall   ;from Misc Tools*** added 27-Jan-92 DAL	php	sei	lda >$e10094+1	sta >oldToBramSetupCall+1	lda >$e10094+2	sta >oldToBramSetupCall+2	lda #ToBramSetupPatch>>8	sta >$e10094+2	lda #ToBramSetupPatch	sta >$e10094+1	plp*** end 27-Jan-92	pea $0001	;special flag to patch TL on ROM 3	pea $0001	;tool set = Tool Locator	pushlong #LocatorCallTable	_SetTSPtr	pea $0000	;system tool	pea $0003	;tool set = misc tools	pushlong #MTCallTable	_SetTSPtr	pea $0001	;special flag to patch DM on ROM 3	pea $0005	;tool set = Desk Manager	pushlong #DeskCallTable	_SetTSPtr	rts	EndP****************************************************************** Tool Locator call table -- patches common to ROM 1 and ROM 3*****************************************************************LocatorCallTable	proc EXPORT	import AcceptRequests	;17-Sep-90 DAL	import SendRequest		;17-Sep-90 DAL	import GetMsgHandle		;25-Sep-90 DAL	import StartUpTools		;17-Nov-90 DAL	import ShutDownTools	;17-Nov-90 DAL	import LoadOneTool		;17-Nov-90 DAL	import LoadTools		;17-Nov-90 DAL	import UnloadOneTool	;25-Nov-90 DALTheBeginning	dc.L (TheEnd-TheBeginning)/4	; call count + 1	dc.L TLBootInit-1		; TLBootInit (0101)	dc.L 0		; TLStartUp  (0201)	dc.L 0		; TLShutDwon (0301)	dc.L 0		; TLVersion  (0401)	dc.L 0		; TLReset    (0501)	dc.L 0		; TLStatus   (0601)	dc.L 0		; NotImp     (0701)	dc.L 0		; NotImp     (0801)	dc.L 0		; GetTSPtr   (0901)	dc.L 0		; SetTSPtr   (0A01)	dc.L 0		; GetFuncPtr (0B01)	dc.L 0		; GetWAP     (0C01)	dc.L 0		; SetWAP     (0D01)	dc.L LoadTools-1		;                   0e01	dc.L LoadOneTool-1		;                   0f01	dc.L UnloadOneTool-1	;                   1001	dc.L 0 		; TLMountVolume     1101	dc.L 0 		; TLTextMountVolume 1201	dc.L 0	 	; SaveTextState     1301	dc.L 0		; RestoreTextState  1401	dc.L 0 		; MesasgeCenter     1501	dc.L 0 		; SetDefaultTPT     1601	dc.L 0 		; MessageByName     1701	dc.L StartupTools-1 	; StartUpTools      1801	dc.L ShutDownTools-1 	; ShutDownTools     1901*** New calls for 6.0	dc.l GetMsgHandle-1		; 1A01  17-Sep-90 DAL	dc.l AcceptRequests-1	; 1B01  17-Sep-90 DAL	dc.l SendRequest-1		; 1C01  17-Sep-90 DALTheEndTLBootInit	lda #0	clc	rtl	EndP****************************************************************** Misc Tools call table -- patches common to ROM 1 and ROM 3*****************************************************************MTCallTable	proc	import UnPackBytes,ConvSeconds,SysBeep2,VersionString	import WaitUntil,StringToText,ShowBootInfo,ScanDevices	import AlertMessage,DoSysPrefsHere 	DC.L (TheEnd-Here)/4 ; num calls +1	DC.L MTInit-1	; PowerUp Initialization	DC.L 0	; application startup	DC.L 0	; application shutdown	DC.L 0	; version number	DC.L 0	; Misc. Tools Reset	DC.L 0	; MTStatus	DC.L 0	; Reserved	DC.L 0	; Reserved	DC.L 0	; Write battery ram	DC.L 0	; Read battery ram	DC.L 0	; Write battery ram	parameter	DC.L 0	; Read battery ram parameter	DC.L 0	; read clock w/ hex	format	DC.L 0	; write clock w/ hex format	DC.L 0	; read clock w/ ascii format	DC.L 0	; set interrupt vector	DC.L 0	; get interrupt vector	DC.L 0	; insert procedure in Heartbeat chain	DC.L 0	; delete procedure from heartbeat chai	DC.L 0	; clear heartbeat chain	DC.L 0	; system death manager	DC.L 0	DC.L 0	; Read Mouse	DC.L 0	; initialize mouse	DC.L 0	; set mouse mode	DC.L 0	; home mouse position to min. clamp	DC.L 0	; clear mouse position to 0	DC.L 0	; set both X and Y clamps	DC.L 0	; get both X and Y clamps	DC.L 0	; set mouse position	DC.L 0	; service mouse interrupt	DC.L 0	; get ID tag	DC.L 0	; delete ID tag	DC.L 0	; get ID tag status	DC.L 0	; enable interrupt source	DC.L 0	; Firmware entry points	DC.L 0	; get tick counter contents	DC.L 0	; Pack bytes	DC.L UnPackBytes-1	; UnPack dem dere bytes	DC.L 0	; This routine munges strings	DC.L 0	; returns IRQ enble	status	DC.L 0	; set absolute device clamps	DC.L 0	; get absolute device clamps	DC.L 0	; 2C03 system beep	dc.L 0	; 2D03 NewBasicInit	; added 07 sep 88	DC.L 0	; 2E03 AddToQueue	; added 10 sep 88	DC.L 0	; 2F03 RemoveFromQueue ; added 10 sep 88	dc.L 0	; 3003 SetInterruptState added 24 Nov 88	dc.L 0	; 3103 GetInterruptState added 24 Nov 88	dc.L 0	; 3203 GetIntStateRecSize added 24 Nov 88	dc.L 0	; 3303 ReadMouse2 Added 13 Jan 89	dc.L 0	; 3403 GetCodeResConverter added 13 Jan 89 {$3403}	dc.L 0	; 3503 GetROMResource added 24 Jan 89 ($3503}	dc.L 0	; 3603 ReleaseROMResource added 24 Jan 89 {$3603}*** 5.0.3	dc.L ConvSeconds-1	; 3703 added 3/14/90*** 6.0	dc.L SysBeep2-1	; 3808 added 17-Sep-90 DAL	dc.L VersionString-1 ;3903 added 5-Dec-90 DAL	dc.l WaitUntil-1	; 3A03 added 6-Jan-91 DAL	dc.l StringToText-1	; 3B03 added 3-Mar-91 DAL	dc.l ShowBootInfo-1	; 3C03 added 29-Mar-91 DAL	dc.l ScanDevices-1	; 3D03 added 29-Mar-91 DAL*** 6.0.1	dc.l AlertMessage-1	; 3E03 added 20-Aug-92 DAL	dc.l DoSysPrefs-1	; 3F03 added 20-Aug-92 DALTheEndMTInit	lda #0	sta >PendingSysBeep2	clc	rtl	EndP****************************************************************** Desk Manager call table -- patches common to ROM 1 and ROM 3*****************************************************************DeskCallTable	proc	import ChooseCDA	import SystemClick,SystemEdit,SystemTask	import SystemEvent,CloseNDAbyWinPtr,CloseAllNDAs2	import FixAppleMenu2,RemoveNDA,GetDeskAccInfo	import CallDeskAcc,GetDeskGlobal	import MonKeyinTheBeginning	DC.L (TheEnd-TheBeginning)/4 ; num calls + 1	DC.L DABootInit-1	; 	; 0105	DC.L 0	;DAStartup-1	; 0205 patched 4-Mar-91 DAL	DC.L 0	;DAShutdown-1	; 0305 patched 4-Mar-91 DAL	DC.L 0	;DAVersion-1	; 	  0405	DC.L 0	; DAReset-1	; 0505	DC.L 0	; DAStatus-1	; 0605	DC.L 0	; oEndCall0-1	; 0705     reserved	DC.L 0	; oEndCall0-1	; 0805     reserved	DC.L 0	; SaveScreen-1	; 0905	DC.L 0	; RestScreen-1	; 0A05	DC.L 0	; SaveAll-1	; 0B05	DC.L 0	; RestAll-1	; 0C05	DC.L 0	; oEndCall0-1	; 0D05	DC.L 0	;InstallNDA-1	; 0E05	DC.L 0	; instcda-1	; 0F05	DC.L 0	; oEndCall0-1	; 1005	DC.L ChooseCDA-1		; 1105	DC.L 0	; oEndCall0-1	; 1205	DC.L 0	; setdastrptr-1	; 1305	DC.L 0	; getdastrptr-1	; 1405	DC.L 0	;OpenNDAentry-1	; 1505	DC.L 0	;CloseNDA-1	; 1605	DC.L SystemClick-1		; 1705	DC.L SystemEdit-1		; 1805	DC.L SystemTask-1		; 1905	DC.L SystemEvent-1		; 1A05	DC.L 0	;GetNumNDAs-1	; 1B05	DC.L CloseNDAbyWinPtr-1 	; 1C05	DC.L CloseAllNDAs2-1	; 1D05	DC.L FixAppleMenu2-1	; 1E05	DC.L 0	;AddToRunQ-1	; 1F05	DC.L 0	;RemoveFromRunQ-1 	; 2005	DC.L 0	; RemoveCDA-1	; 2105	DC.L RemoveNDA-1		; 2205	dc.L GetDeskAccInfo-1	; 2305  19-Sep-90 DAL	dc.L CallDeskAcc-1		; 2405  19-Sep-90 DAL	dc.l GetDeskGlobal-1	; 2505  19-Feb-91 DALTheEndDABootInit	lda #0	sta >RealDeskStatus	lda #monkeyin	sta >KeyInput	clc	rtl	EndP	END